-- Knowledge base seed (W2 Support): published answers written from product facts.
-- Edited later in the admin panel. INSERT OR IGNORE keeps admin-made slugs safe.
-- Answers use [text](/path) links and `code`; the site renders that small markup.
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_pricing-plans', 'pricing-plans', 'How much does Ingot UI cost?', 'Free is $0 and includes the Loopo system. Pro is $7 a month or $59 a year and unlocks all six design systems, every component in code and Figma, and unlimited MCP. Lifetime is one payment of $29 for the first 200 buyers, then $99. See [Pricing](/pricing).', 'price, cost, plans, pricing, pro, how much, monthly, yearly, subscription', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_lifetime-deal', 'lifetime-deal', 'What is the Lifetime deal?', 'Lifetime is one payment of $29 for the first 200 buyers, then $99. You get everything in Pro forever, including future systems and dark mode. The spots left on [Pricing](/pricing) are counted from real orders.', 'lifetime, one time, pay once, deal, launch deal, 200 buyers, spots left', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_refund-policy', 'refund-policy', 'Can I get a refund?', 'Yes. Every paid plan has a 7-day refund, no questions asked. Write to support@ingotui.com from the email you paid with, or use the form on [Support](/support#contact).', 'refund, money back, 7 days, chargeback, guarantee', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_cancel-subscription', 'cancel-subscription', 'How do I cancel Pro?', 'Open [Account](/account) and choose Manage billing, then cancel. Pro stays active until the end of the period you paid for, and you are not charged again. Anything you already copied stays yours.', 'cancel, unsubscribe, stop subscription, renewal, manage billing', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_invoices-receipts', 'invoices-receipts', 'Where do I find my invoice or receipt?', 'A receipt is emailed to you after every payment, and your receipts are listed on [Account](/account) under billing. Need a company name or VAT number on it? Use Manage billing on the same page.', 'invoice, receipt, bill, vat, tax, company details, billing history', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_checkout-opening', 'checkout-opening', 'How do I pay, and is checkout open?', 'Checkout is opening soon. Until then the buy buttons on [Pricing](/pricing) take your email and we write when it opens. Payments run through Lemon Squeezy, our merchant of record, which takes major cards and handles sales tax.', 'pay, payment, checkout, buy, purchase, card, waitlist, lemon squeezy, upgrade', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_team-plan', 'team-plan', 'Is there a plan for my team?', 'Plans are per person today. For several seats, write to support@ingotui.com with the number of people and we will set it up for you.', 'team, seats, company, colleagues, organisation, multiple users', 'Billing', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_commercial-use', 'commercial-use', 'Can I use Ingot UI in commercial and client projects?', 'Yes. Free and paid components can be used in unlimited personal and commercial projects, including client work. The full terms are in the [licence](/docs#license).', 'licence, license, commercial, client work, client projects, allowed, terms, legal', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_stop-paying', 'stop-paying', 'What happens to my code if I stop paying?', 'Everything you already copied or shipped stays yours to use. You only lose the ability to copy new Pro items. Free components stay free forever.', 'stop paying, expire, keep code, after subscription ends, ownership, lose access', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_resell-library', 'resell-library', 'Can I resell or redistribute the components?', 'No. You can ship the components inside your own products, but you may not resell or redistribute the library itself as a UI kit, template pack or competing library. See the [licence](/docs#license).', 'resell, redistribute, sell, ui kit, template, marketplace, licence', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_free-components', 'free-components', 'What do I get for free?', 'The Loopo design system, the free components in React code, every icon and the MCP server with 50 calls a day. Free components are free forever, for commercial use too. [Browse them](/systems/loopo).', 'free, free plan, loopo, trial, try, no cost, gratis', 'Licence', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_install-cli', 'install-cli', 'How do I install the components?', 'In a React project with Tailwind v4, run `npx ingotui init` once, then `npx ingotui add button kpi-card` for the components you want. The CLI writes the files and their dependencies into your project. More in [Docs](/docs#install).', 'install, setup, cli, npx, npm, add component, ingotui init, command', 'Install', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_shadcn-registry', 'shadcn-registry', 'Can I install with shadcn?', 'Yes. Every free component is a shadcn registry item, for example `npx shadcn add https://ingotui.com/r/button.json`. Pro components install through the CLI or MCP with your API key.', 'shadcn, registry, shadcn add', 'Install', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_frameworks', 'frameworks', 'Which frameworks does it work with?', 'Components are plain React 19 and Tailwind CSS v4 files, so they work in Next.js, Vite and Remix. Interactive parts use Base UI. Vue, Svelte and Angular are not supported.', 'framework, react, nextjs, vite, remix, vue, svelte, angular, requirements, compatible', 'Install', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_tokens-theming', 'tokens-theming', 'How do theming and design tokens work?', 'Each system is a set of `--fu-*` CSS variables mapped to Tailwind utilities such as `bg-fu-surface`. Import the theme file and a system file in your global CSS, then switch systems by swapping the file or with `data-system`. See [Tokens](/docs#tokens).', 'design tokens, theme, theming, css variables, tailwind, colors, brand, customise', 'Install', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_dark-mode', 'dark-mode', 'Is there dark mode?', 'Not yet. Light mode ships at launch and dark mode is the first update after it. Pro and Lifetime get it at no extra cost.', 'dark mode, dark theme, night mode, roadmap', 'Install', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_design-systems', 'design-systems', 'Which design systems are included?', 'Six dashboard systems: Loopo, MailPulse, Auton, Axon, Veriq and Vantage. Loopo is free; the other five come with Pro or Lifetime, and new components are added every week. See [Systems](/systems).', 'design systems, loopo, mailpulse, auton, axon, veriq, vantage, included, how many', 'Install', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_connect-mcp', 'connect-mcp', 'How do I connect the MCP server to my AI agent?', 'Create an API key on [Account](/account), then add the server `https://mcp.ingotui.com/mcp` to Claude Code, Cursor, VS Code or Codex with that key. Copy-ready setup for each client is on the [MCP page](/mcp).', 'mcp, agent, claude code, cursor, codex, vs code, connect, setup, ai, server', 'MCP and agents', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_api-key', 'api-key', 'Where do I get an API key?', 'Sign in, open [Account](/account) and create a key under API keys. It is shown once and stored hashed, so save it somewhere safe. Lost it? Delete it and create a new one.', 'api key, token, bearer, authorization, lost key, create key', 'MCP and agents', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_mcp-limits', 'mcp-limits', 'Is there a limit on MCP calls?', 'The free plan includes 50 MCP calls a day. Pro and Lifetime have unlimited MCP and CLI use. Your agent can check its plan and limits with the `get_usage` tool.', 'limit, mcp calls, quota, rate limit, 50 calls, unlimited, usage', 'MCP and agents', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_agent-first-steps', 'agent-first-steps', 'What should I ask my agent first?', 'Ask it to run `init_project` first. It writes the tokens, the theme bridge and a rules file, so later sessions keep using the system. Then ask for a screen, for example an analytics page with KPI cards and a chart. See the [MCP page](/mcp).', 'init project, init_project, prompt, agent rules, first steps, scaffold screen', 'MCP and agents', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_copy-to-figma', 'copy-to-figma', 'How do I copy a component to Figma?', 'Open any component page and choose Copy to Figma, then paste in your Figma file with Cmd+V or Ctrl+V. It arrives as editable layers, and charts and icons come in as vectors.', 'figma, copy to figma, paste, clipboard, layers, vectors', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-kit', 'figma-kit', 'Is there a full Figma kit?', 'Yes. Pro and Lifetime include the full Figma kit for each system, with variables, components and screens. Free users can copy the Loopo items to Figma one by one.', 'figma kit, figma file, figma library, variables, screens', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_figma-paste-issue', 'figma-paste-issue', 'Copy to Figma does not paste anything. What can I do?', 'Paste right after copying, into a Figma design file (not FigJam), and use the desktop app or a Chromium browser if the browser blocks clipboard access. If it still fails, send us the component link through [Support](/support#contact).', 'paste not working, clipboard, broken, nothing happens, error, bug', 'Figma', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_free-copy-limit', 'free-copy-limit', 'Why am I asked to sign up after a few copies?', 'Without an account you can copy 5 items. A free account gives unlimited copies of the free components and the Loopo system. [Create one](/sign-up) in a few seconds, no card needed.', 'limit, 5 copies, copy limit, sign up, without an account, blocked, free account', 'Account', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_forgot-password', 'forgot-password', 'I forgot my password or cannot log in.', 'Write to support@ingotui.com from your account email and we will reset access for you. Check that you are using the same email you signed up with on [Log in](/sign-in).', 'login, sign in, password, forgot, reset, locked out', 'Account', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_delete-account', 'delete-account', 'How do I delete my account or data?', 'Email support@ingotui.com from your account email and ask for deletion. We remove your account, API keys and saved items, and confirm by email.', 'delete account, close account, remove data, gdpr, privacy, erase', 'Account', 1, CAST(strftime('%s','now') AS INTEGER));
INSERT OR IGNORE INTO `kb_article` (`id`, `slug`, `question`, `answer`, `keywords`, `category`, `published`, `updatedAt`) VALUES ('kb_contact-support', 'contact-support', 'How do I contact a person?', 'Write to support@ingotui.com or use the form on [Support](/support#contact). We reply by email, usually within a day.', 'contact, email, human, person, talk to someone, support team', 'Account', 1, CAST(strftime('%s','now') AS INTEGER));
